export function makePeople(seed = 808): Person[] {
  let s = seed; const random = () => { s = (Math.imul(1664525, s) + 1013904223) >>> 0; return s / 4294967296; };
  return (['employee','contractor','candidate'] as const).flatMap((kind, k) => Array.from({ length: [150,40,60][k] }, (_, i) => {
    const r = i % roles.length; const base = roleSkills[r]; const demonstrated: Record<string,number> = {};
    base.forEach((skill,j) => { if (j < 3 || random() > .3) demonstrated[skill] = 65 + Math.floor(random()*31); });
    const p: Person = { id: `${kind}-${String(i+1).padStart(3,'0')}`, name: `${firstNames[i%25]} ${lastNames[Math.floor(i/25)+k]}`, kind, role: roles[r], location: locations[i%6], experience: 2+Math.floor(random()*10), salary: 10+Math.round(random()*200)/10, rate: 650+Math.floor(random()*9)*100, availability: 7+Math.floor(random()*7)*7, performance: 65+Math.floor(random()*31), learning: Math.floor(random()*100), promotionEligible: random() > .4, skills: demonstrated, projects: [`${['Payments modernisation','Customer analytics','Cloud migration','Operations platform','Risk reporting'][i%5]}`], certifications: [base[i%5]+' practitioner'], sourceId: kind==='employee'?'hris':kind==='contractor'?'vms':'ats' };
    // Three trainable employees and two contractors form a reproducible hybrid example.
    if (r===0 && kind==='employee') { p.availability = i < 30 ? 7 : 75; p.experience=5; p.salary=15; p.skills={Python:95,FastAPI:90,PostgreSQL:90,AWS:80}; p.performance=92; }
    if (r===0 && kind==='contractor') { p.availability=i<20?7:60; p.experience=6; p.rate=800; p.skills={Python:95,FastAPI:90,PostgreSQL:90,Docker:90,AWS:90}; }
    return p;
  }));
}
